eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   WHATSAPP_NUMERO: () => (/* binding */ WHATSAPP_NUMERO),\n/* harmony export */   acolhimento: () => (/* binding */ acolhimento),\n/* harmony export */   apoio: () => (/* binding */ apoio),\n/* harmony export */   chamada: () => (/* binding */ chamada),\n/* harmony export */   contato: () => (/* binding */ contato),\n/* harmony export */   encontros: () => (/* binding */ encontros),\n/* harmony export */   hero: () => (/* binding */ hero),\n/* harmony export */   linkWhatsApp: () => (/* binding */ linkWhatsApp),\n/* harmony export */   mensagens: () => (/* binding */ mensagens),\n/* harmony export */   menu: () => (/* binding */ menu),\n/* harmony export */   oficinas: () => (/* binding */ oficinas),\n/* harmony export */   rodape: () => (/* binding */ rodape),\n/* harmony export */   site: () => (/* binding */ site),\n/* harmony export */   transparencia: () => (/* binding */ transparencia)\n/* harmony export */ });\n// ============================================================\n// CONTEÚDO DO SITE — PROJETO PAI\n// Edite aqui textos, fotos e o número do WhatsApp.\n// ============================================================\n// TROQUE pelo número oficial, com código do país e DDD, só dígitos.\n// Exemplo: \"5585999999999\"\nconst WHATSAPP_NUMERO = \"5500000000000\";\nconst linkWhatsApp = (mensagem)=>`https://wa.me/${WHATSAPP_NUMERO}?text=${encodeURIComponent(mensagem)}`;\nconst mensagens = {\n    encontros: \"Ol\\xe1! Gostaria de saber as datas dos pr\\xf3ximos encontros do Projeto PAI.\",\n    apoiador: \"Ol\\xe1! Gostaria de saber como posso apoiar o Projeto PAI.\",\n    financeira: \"Ol\\xe1! Gostaria de saber como posso fazer uma contribui\\xe7\\xe3o financeira para o Projeto PAI.\",\n    alimentos: \"Ol\\xe1! Gostaria de informa\\xe7\\xf5es sobre doa\\xe7\\xe3o de alimentos para o Projeto PAI.\",\n    materiais: \"Ol\\xe1! Gostaria de saber quais materiais o Projeto PAI est\\xe1 precisando.\",\n    contato: \"Ol\\xe1! Quero apoiar o Projeto PAI. Podemos conversar?\"\n};\nconst site = {\n    nome: \"Projeto PAI\",\n    nomeCompleto: \"Programa de Apadrinhamento Infantil\",\n    titulo: \"Projeto PAI — Programa de Apadrinhamento Infantil\",\n    descricao: \"Oficinas educativas, musicais, art\\xedsticas e recreativas, caf\\xe9 da manh\\xe3 e almo\\xe7o para as crian\\xe7as, dois s\\xe1bados por m\\xeas. Conhe\\xe7a o Projeto PAI e saiba como apoiar.\"\n};\nconst menu = [\n    {\n        rotulo: \"Atividades\",\n        href: \"#oficinas\"\n    },\n    {\n        rotulo: \"Acolhimento\",\n        href: \"#acolhimento\"\n    },\n    {\n        rotulo: \"Apoie\",\n        href: \"#apoie\"\n    },\n    {\n        rotulo: \"Transpar\\xeancia\",\n        href: \"#transparencia\"\n    },\n    {\n        rotulo: \"Contato\",\n        href: \"#contato\"\n    }\n];\nconst hero = {\n    titulo: \"Aprendizagem, arte, m\\xfasica e conviv\\xeancia para as crian\\xe7as.\",\n    texto: \"O Projeto PAI — Programa de Apadrinhamento Infantil — desenvolve atividades voltadas \\xe0 aprendizagem, \\xe0 express\\xe3o art\\xedstica, \\xe0 musicaliza\\xe7\\xe3o, \\xe0 conviv\\xeancia e ao desenvolvimento das crian\\xe7as.\",\n    resumo: \"Dois s\\xe1bados por m\\xeas, das 8h \\xe0s 11h, com caf\\xe9 da manh\\xe3 e almo\\xe7o.\",\n    botaoPrincipal: \"Seja um apoiador\",\n    botaoSecundario: \"Conhe\\xe7a nossas atividades\"\n};\nconst encontros = {\n    titulo: \"Nossos encontros\",\n    itens: [\n        {\n            icone: \"calendario\",\n            rotulo: \"Frequ\\xeancia\",\n            valor: \"Dois s\\xe1bados por m\\xeas\"\n        },\n        {\n            icone: \"relogio\",\n            rotulo: \"Hor\\xe1rio\",\n            valor: \"Das 8h \\xe0s 11h\"\n        },\n        {\n            icone: \"atividades\",\n            rotulo: \"Atividades\",\n            valor: \"Oficinas educativas, musicais, art\\xedsticas e recreativas\"\n        },\n        {\n            icone: \"alimentacao\",\n            rotulo: \"Acolhimento\",\n            valor: \"Caf\\xe9 da manh\\xe3 e almo\\xe7o\"\n        }\n    ],\n    nota: \"Para saber as datas dos pr\\xf3ximos encontros, fale com a equipe pelos canais oficiais.\",\n    botao: \"Saiba mais pelo WhatsApp\"\n};\nconst oficinas = {\n    titulo: \"Muito al\\xe9m de atividades: oportunidades para crescer.\",\n    texto: \"No Projeto PAI, cada encontro \\xe9 uma oportunidade de aprender, desenvolver talentos, fortalecer v\\xednculos e viver novas experi\\xeancias. Por meio de oficinas educativas, art\\xedsticas e recreativas, buscamos contribuir para o desenvolvimento integral das crian\\xe7as.\",\n    // Para usar foto real e autorizada, preencha \"foto\" com o caminho em /public (ex.: \"/fotos/musica.jpg\").\n    cards: [\n        {\n            icone: \"livro\",\n            cor: \"azul\",\n            titulo: \"Refor\\xe7o escolar\",\n            descricao: \"Aprender com mais confian\\xe7a, superar dificuldades e fortalecer os conhecimentos escolares. O refor\\xe7o escolar busca apoiar a aprendizagem das crian\\xe7as de maneira acolhedora e participativa.\",\n            foto: \"\"\n        },\n        {\n            icone: \"musica\",\n            cor: \"amarelo\",\n            titulo: \"Aula de m\\xfasica\",\n            descricao: \"Um espa\\xe7o para explorar sons, desenvolver a criatividade, descobrir talentos e aprender por meio da m\\xfasica, estimulando a express\\xe3o e a conviv\\xeancia.\",\n            foto: \"\"\n        },\n        {\n            icone: \"paleta\",\n            cor: \"vermelho\",\n            titulo: \"Arte e artesanato\",\n            descricao: \"Atividades art\\xedsticas e manuais que incentivam a imagina\\xe7\\xe3o, a coordena\\xe7\\xe3o motora, a criatividade e a express\\xe3o individual de cada crian\\xe7a.\",\n            foto: \"\"\n        },\n        {\n            icone: \"puzzle\",\n            cor: \"verde\",\n            titulo: \"Recrea\\xe7\\xe3o com prop\\xf3sito\",\n            descricao: \"Brincadeiras, din\\xe2micas e atividades recreativas que promovem a socializa\\xe7\\xe3o, a coopera\\xe7\\xe3o, o respeito e o aprendizado de valores importantes para a vida.\",\n            foto: \"\"\n        }\n    ]\n};\nconst chamada = {\n    titulo: \"O Projeto PAI precisa de voc\\xea.\",\n    texto: \"Com sua contribui\\xe7\\xe3o, podemos continuar promovendo aprendizagem, criatividade, conviv\\xeancia e cuidado com as crian\\xe7as.\",\n    botaoPrincipal: \"Seja um apoiador\",\n    botaoSecundario: \"Conhe\\xe7a nossas atividades\"\n};\nconst acolhimento = {\n    titulo: \"Cuidar tamb\\xe9m \\xe9 alimentar.\",\n    texto: \"Durante os encontros do Projeto PAI, as crian\\xe7as contam com momentos de alimenta\\xe7\\xe3o, incluindo caf\\xe9 da manh\\xe3 e almo\\xe7o. Esse cuidado faz parte da acolhida e da organiza\\xe7\\xe3o das atividades, contribuindo para que cada encontro seja vivido com aten\\xe7\\xe3o, dignidade e carinho.\",\n    destaques: [\n        {\n            icone: \"alimentacao\",\n            cor: \"amarelo\",\n            titulo: \"Caf\\xe9 da manh\\xe3\",\n            descricao: \"Um momento de acolhida e conviv\\xeancia durante o encontro.\",\n            foto: \"\"\n        },\n        {\n            icone: \"alimentacao\",\n            cor: \"verde\",\n            titulo: \"Almo\\xe7o\",\n            descricao: \"Uma refei\\xe7\\xe3o compartilhada, servida com aten\\xe7\\xe3o e carinho.\",\n            foto: \"\"\n        }\n    ]\n};\nconst apoio = {\n    titulo: \"Ajude-nos a continuar transformando vidas!\",\n    texto: [\n        \"Para que o Projeto PAI continue oferecendo oficinas, atividades educativas, momentos de conviv\\xeancia, caf\\xe9 da manh\\xe3 e almo\\xe7o \\xe0s crian\\xe7as, precisamos da ajuda de pessoas que acreditam nessa miss\\xe3o.\",\n        \"Sua oferta, contribui\\xe7\\xe3o ou doa\\xe7\\xe3o pode fazer a diferen\\xe7a. Cada gesto de generosidade ajuda a fortalecer esse trabalho e a criar novas oportunidades para nossas crian\\xe7as.\"\n    ],\n    foto: \"\",\n    formas: [\n        {\n            icone: \"coracao\",\n            titulo: \"Ofertas e contribui\\xe7\\xf5es financeiras\",\n            descricao: \"Contribua financeiramente para ajudar na manuten\\xe7\\xe3o das atividades, na aquisi\\xe7\\xe3o de materiais e na realiza\\xe7\\xe3o dos encontros do Projeto PAI.\",\n            botao: \"Quero contribuir\",\n            mensagem: \"financeira\"\n        },\n        {\n            icone: \"alimentacao\",\n            titulo: \"Doa\\xe7\\xe3o de alimentos\",\n            descricao: \"Ajude a fortalecer os momentos de alimenta\\xe7\\xe3o do projeto por meio de doa\\xe7\\xf5es de alimentos, conforme as necessidades e orienta\\xe7\\xf5es da organiza\\xe7\\xe3o.\",\n            botao: \"Quero doar alimentos\",\n            mensagem: \"alimentos\"\n        },\n        {\n            icone: \"paleta\",\n            titulo: \"Doa\\xe7\\xe3o de materiais\",\n            descricao: \"Materiais escolares, instrumentos musicais, itens para artesanato e outros materiais adequados \\xe0s oficinas podem contribuir para as experi\\xeancias de aprendizagem e criatividade das crian\\xe7as.\",\n            botao: \"Quero ajudar com materiais\",\n            mensagem: \"materiais\"\n        }\n    ]\n};\nconst transparencia = {\n    titulo: \"Cada contribui\\xe7\\xe3o merece responsabilidade.\",\n    texto: \"O Projeto PAI valoriza a confian\\xe7a de cada pessoa que apoia sua miss\\xe3o. As contribui\\xe7\\xf5es s\\xe3o importantes para ajudar a manter as atividades e atender \\xe0s necessidades do projeto.\",\n    itens: [\n        \"Relat\\xf3rios de atividades\",\n        \"Presta\\xe7\\xe3o de contas\",\n        \"Relat\\xf3rios anuais\",\n        \"Principais necessidades do projeto\",\n        \"Informa\\xe7\\xf5es sobre a aplica\\xe7\\xe3o dos recursos\",\n        \"Formas oficiais de contribui\\xe7\\xe3o\"\n    ],\n    aviso: \"Os documentos ser\\xe3o publicados aqui assim que estiverem dispon\\xedveis.\"\n};\nconst contato = {\n    titulo: \"Quer apoiar o Projeto PAI?\",\n    texto: \"Seja por meio de ofertas, contribui\\xe7\\xf5es financeiras, alimentos ou materiais para nossas oficinas, toda ajuda deve ser combinada com a equipe do Projeto PAI para atender \\xe0s necessidades reais das atividades.\",\n    intro: \"Pelo WhatsApp oficial voc\\xea pode:\",\n    itens: [\n        \"Conhecer as necessidades atuais\",\n        \"Consultar as formas de contribui\\xe7\\xe3o\",\n        \"Combinar a entrega de doa\\xe7\\xf5es\",\n        \"Solicitar informa\\xe7\\xf5es sobre apoio recorrente\",\n        \"Conversar sobre poss\\xedveis parcerias\"\n    ],\n    botao: \"Falar pelo WhatsApp\"\n};\nconst rodape = {\n    texto: \"Projeto PAI — Programa de Apadrinhamento Infantil\"\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./data/conteudo.js\n");

